[Form]
public class CELTSalesInvoices extends FormRun
{
    // Per-row cache for the newest writeback of the row being rendered: the 16 status columns
    // are display methods that all read the same row, so the first one pays the select and the
    // rest reuse it. Keyed on the journal RecId (InvoiceId can repeat across blank rows).
    ClearTaxEInvoiceResponseTable wbCache;
    RecId                         wbCacheJourRecId;
}

/// <summary>
/// All posted sales invoices, newest first, with the Clear e-invoice status columns.
/// </summary>
public void init()
{
    super();

    CustInvoiceJour_ds.query().dataSourceTable(tableNum(CustInvoiceJour)).addSortField(fieldNum(CustInvoiceJour, InvoiceDate), SortOrder::Descending);
    // Ties on the date need a defined order too: without a second key, same-date invoices
    // come back in whatever order SQL picks, so the grid appeared to shuffle after every
    // re-read (e.g. when Generate e-invoice refreshes the grid).
    CustInvoiceJour_ds.query().dataSourceTable(tableNum(CustInvoiceJour)).addSortField(fieldNum(CustInvoiceJour, InvoiceId), SortOrder::Descending);

    this.applyCountryVisibility();
}

/// <summary>
/// Checkbox-driven visibility (Company capabilities setup) plus the country layout: France
/// keeps its PPF lifecycle dashboard columns; every other seller country shows the PINT
/// dashboard columns from the UAE ERP dashboard spec (icon, company, voucher, dates, fiscal
/// year, customer name and VAT, self-billing, document id, errors, statuses).
/// </summary>
private void applyCountryVisibility()
{
    boolean lifecycleOn   = CELTLifecycleActionService::isLifecycleActionsVisible();
    boolean selfBillingOn = CELTLifecycleActionService::isSelfBillingVisible();
    boolean franceView    = strUpr(new CELTLifecycleActionService().sellerCountryIsoCode()) == CELTConstants::DefaultLifecycleCountry;

    element.design().controlName(formControlStr(CELTSalesInvoices, BtnGenerateEInvoice)).visible(selfBillingOn);
    element.design().controlName(formControlStr(CELTSalesInvoices, BtnLifecycleMenu)).visible(lifecycleOn && franceView);
    element.design().controlName(formControlStr(CELTSalesInvoices, BtnPaymentHistory)).visible(lifecycleOn && franceView);
    element.design().controlName(formControlStr(CELTSalesInvoices, Grid_PaymentHistory)).visible(lifecycleOn && franceView);
    element.design().controlName(formControlStr(CELTSalesInvoices, BtnActionLog)).visible(lifecycleOn && franceView);

    // PINT dashboard columns (every non-France seller country).
    // Icon column hidden everywhere for now (user request) - flip false back to !franceView to re-enable.
    this.toggle(formControlStr(CELTSalesInvoices, Grid_Icon), false);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_Company), !franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_AccountingDocNo), !franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PostingDate), !franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_DocumentDate), !franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_FiscalYear), !franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_VATNum), !franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_SelfBilling), !franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_GovRepStatus), !franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_GovRepReasonMsg), !franceView);

    // France-only columns.
    this.toggle(formControlStr(CELTSalesInvoices, Grid_InvoiceDate), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_DueDate), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_InvoiceAccount), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_SalesId), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_InvoiceAmount), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_CurrencyCode), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_EInvoiceStatus), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_ActionTaken), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_DocumentStatusReasonCode), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PPFSubmissionStatus), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PPFSubmissionReasonCode), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PPFSubmissionReasonMsg), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PPFLcSubmittedStatus), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PPFLcSubmittedReasonCode), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PPFLcSubmittedReasonMsg), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PPFLcPmtCollectedStatus), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PPFLcPmtCollectedReasonCode), franceView);
    this.toggle(formControlStr(CELTSalesInvoices, Grid_PPFLcPmtCollectedReasonMsg), franceView);
}

/// <summary>
/// Shows or hides one design control by name.
/// </summary>
private void toggle(str _controlName, boolean _visible)
{
    element.design().controlName(_controlName).visible(_visible);
}

/// <summary>
/// Traffic-light state for a row, per the UAE dashboard spec: Red when an error is present
/// or any status reads FAILED / REJECTED; Yellow while still in flight (OPEN / PENDING /
/// PROCESSING / NOT_SUBMITTED - including no writeback yet); Green for the rest.
/// </summary>
/// <param name = "_jour">the journal row being rendered</param>
/// <returns>the icon column text; the row cell color follows it in displayOption</returns>
public str iconStateOf(CustInvoiceJour _jour)
{
    ClearTaxEInvoiceResponseTable wb = this.findWriteback(_jour);
    str statuses = strUpr(wb.Success + '|' + wb.STATUS + '|' + wb.PAExchangeStatus + '|' + wb.PPFSubmissionStatus);
    str errorMsg = wb.ErrorDetails != '' ? wb.ErrorDetails : wb.ERROR;

    if (wb.RecId == 0)
    {
        // Nothing sent to Clear yet counts as not submitted.
        return "@CELTLabels:IconYellow";
    }

    if (errorMsg != ''
        || strScan(statuses, 'FAIL', 1, strLen(statuses)) > 0
        || strScan(statuses, 'REJECT', 1, strLen(statuses)) > 0
        || strScan(statuses, 'FALSE', 1, strLen(statuses)) > 0)
    {
        return "@CELTLabels:IconRed";
    }

    if (strScan(statuses, 'OPEN', 1, strLen(statuses)) > 0
        || strScan(statuses, 'PENDING', 1, strLen(statuses)) > 0
        || strScan(statuses, 'PROCESSING', 1, strLen(statuses)) > 0
        || strScan(statuses, 'NOT_SUBMITTED', 1, strLen(statuses)) > 0)
    {
        return "@CELTLabels:IconYellow";
    }

    return "@CELTLabels:IconGreen";
}

/// <summary>
/// The newest Clear writeback row for the invoice, cached per journal row so the grid's
/// status columns cost one select per rendered row instead of one per column.
/// </summary>
/// <param name = "_jour">the journal row being rendered</param>
/// <returns>newest writeback row; an empty buffer when none has landed</returns>
public ClearTaxEInvoiceResponseTable findWriteback(CustInvoiceJour _jour)
{
    if (wbCacheJourRecId != _jour.RecId)
    {
        wbCache.clear();

        if (_jour.InvoiceId != '')
        {
            // Match current rows (InvoiceId) and legacy-shaped rows (invoice number in
            // DocumentId), like the response log's filter. Newest by creation time - RecId
            // order is not chronological across AOS sessions (per-AOS id blocks).
            select firstonly wbCache
                order by CreatedDateTime desc, RecId desc
                where wbCache.InvoiceId == _jour.InvoiceId
                   || wbCache.DocumentId == _jour.InvoiceId;
        }

        wbCacheJourRecId = _jour.RecId;
    }

    return wbCache;
}

/// <summary>
/// Forgets the cached writeback row so the next render re-reads it from the table.
/// </summary>
public void invalidateWritebackCache()
{
    wbCacheJourRecId = 0;
}

/// <summary>
/// Re-reads the grid after an action - the sync helper refreshes its caller through this
/// method. The writeback cache must be dropped first, or the re-render of the current row
/// would show the pre-action values.
/// </summary>
/// <param name = "_retainPosition">keep the cursor on the current row</param>
public void research(boolean _retainPosition = true)
{
    this.invalidateWritebackCache();
    CustInvoiceJour_ds.research(_retainPosition);
}

public void executeQuery()
{
    element.invalidateWritebackCache();
    super();
}

public void research(boolean _retainPosition = false)
{
    element.invalidateWritebackCache();
    super(_retainPosition);
}

/// <summary>Clear document id - from the newest writeback, else the journal's stamped id.</summary>
display str documentId(CustInvoiceJour _jour)
{
    // Clear assigns a document id even to a failed submission, and the dashboard shows it
    // whenever one exists (UAE ERP dashboard spec) - the outcome lives in the error and
    // status columns, not in this identifier.
    ClearTaxEInvoiceResponseTable wb = element.findWriteback(_jour);
    return wb.DocumentId != '' ? wb.DocumentId : _jour.CELTDocumentId;
}

display str errorDetails(CustInvoiceJour _jour)
{
    // France writes the message into ErrorDetails; Clear's MEA (UAE) backend into ERROR.
    ClearTaxEInvoiceResponseTable wb = element.findWriteback(_jour);
    return wb.ErrorDetails != '' ? wb.ErrorDetails : wb.ERROR;
}

/// <summary>
/// Colors the icon cell red / yellow / green to match the icon state (UAE dashboard spec).
/// </summary>
public void displayOption(Common _record, FormRowDisplayOption _options)
{
    CustInvoiceJour jour  = _record as CustInvoiceJour;
    str             state = element.iconStateOf(jour);

    // Excel-style pastel fills; the default text stays readable on all three.
    if (state == "@CELTLabels:IconRed")
    {
        _options.backColor(WinAPI::RGB2int(255, 199, 206));
    }
    else if (state == "@CELTLabels:IconYellow")
    {
        _options.backColor(WinAPI::RGB2int(255, 235, 156));
    }
    else
    {
        _options.backColor(WinAPI::RGB2int(198, 239, 206));
    }

    _options.affectedElementsByControl(element.design().controlName(formControlStr(CELTSalesInvoices, Grid_Icon)).id());
    super(_record, _options);
}

display str iconState(CustInvoiceJour _jour)
{
    // The cell shows only its color fill (set in displayOption); the state text stays internal.
    return '';
}

display str companyId(CustInvoiceJour _jour)
{
    return _jour.DataAreaId;
}

display str fiscalYear(CustInvoiceJour _jour)
{
    // The writeback carries the fiscal year when the backend sets one; otherwise the
    // invoice date's calendar year stands in.
    ClearTaxEInvoiceResponseTable wb = element.findWriteback(_jour);
    return wb.FiscalYear != '' ? wb.FiscalYear : int2Str(year(_jour.InvoiceDate));
}

display str selfBilling(CustInvoiceJour _jour)
{
    // A sales invoice is self-billed only when the buyer issued it: the writeback then
    // carries a SELF token, or the UNTDID 1001 self-billed codes (389 invoice, 261
    // credit note) in its type fields.
    ClearTaxEInvoiceResponseTable wb = element.findWriteback(_jour);
    str flowText = strUpr(wb.EInvoiceType + '|' + wb.Flow + '|' + wb.InvoiceType);

    boolean selfBilled = strScan(flowText, 'SELF', 1, strLen(flowText)) > 0
        || wb.InvoiceType == '389' || wb.InvoiceType == '261'
        || wb.DOC_TYPE    == 389   || wb.DOC_TYPE    == 261;

    return selfBilled ? enum2Str(NoYes::Yes) : enum2Str(NoYes::No);
}

display str warningDetails(CustInvoiceJour _jour)
{
    return element.findWriteback(_jour).WarningDetails;
}

/// <summary>The last lifecycle action sent for the document (blank when none yet).</summary>
display str actionTaken(CustInvoiceJour _jour)
{
    ClearTaxEInvoiceResponseTable wb = element.findWriteback(_jour);
    return wb.LastAction == CELTLifecycleAction::None ? '' : enum2Str(wb.LastAction);
}

